it(
  '[AC-B2-04r#4] 仍不一致的不入批且同账单同单差错不重复；补充时新发现的不一致按目标账单月登记',
  async () => {
    const h = fixture(database.db);
    const stale = await order(h);
    await settlement(h, stale, { settle_commission_fen: 2000n });
