        await catchUp(db, clock, queue, ports);
        expect(queue.sent.slice(sentBefore).map(plainView)).toStrictEqual([
          plainBillSend(APP, TAOBAO, NEXT_BILL_DAY),
        ]);
      });
    });
  },
  TIMEOUT,
);

